import type * as React from 'react'

import { Separator } from '@/components/separator'
import { cn } from '@/lib/utils'

/**
 * A horizontal divider broken by a centred label — e.g. the "or" rule that
 * separates one sign-in method from another in a login form.
 *
 * Always renders a label (defaulting to "or"); it is not a plain horizontal
 * rule. For an unbroken divider, use the `Separator` component instead.
 *
 * The two flanking rules are rendered `decorative` (role="none") because the
 * visible label already conveys the boundary to assistive tech; exposing two
 * `role="separator"` elements either side of it would be redundant noise.
 */
function LabeledSeparator({
  className,
  children = 'or',
  ref,
  ...props
}: React.ComponentProps<'div'> & { children?: React.ReactNode }) {
  return (
    <div
      ref={ref}
      data-slot='labeled-separator'
      className={cn('flex items-center gap-3', className)}
      {...props}
    >
      <Separator decorative className='flex-1' />
      <span
        data-slot='labeled-separator-content'
        className='shrink-0 text-sm text-muted-foreground'
      >
        {children}
      </span>
      <Separator decorative className='flex-1' />
    </div>
  )
}

export { LabeledSeparator }

export type LabeledSeparatorProps = React.ComponentProps<typeof LabeledSeparator>

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

/**
 * Resolves a cva variant prop to its default once, so the value fed to cva,
 * to the `data-*` attribute and to anything else that reads it agrees.
 *
 * cva reads an explicit `null` as "no variant" (no classes for that axis) but
 * `undefined` and `''` as "use `defaultVariants`", while `??` falls through
 * only for `null` and `undefined`. A component that wrote `data-color={color
 * ?? DEFAULT}` beside `variants({ color })` therefore advertised the default
 * with none of its classes for `null`, and `''` for `''`. `||` covers all
 * three, and every variant key here is a non-empty string, so a falsy value
 * is never a member.
 */
export function resolveVariant<T extends string>(value: T | null | undefined, fallback: T): T {
  return value || fallback
}
